import java.io.*;
import java.math.*;
import java.nio.charset.Charset;
import java.security.MessageDigest;
import java.sql.*;
import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.*;

public class BankBatchJob {

    // Per requirements: single literal string, must start with jdbc:h2: and include MODE=DB2 and /app/output/bankdb
    private static final String JDBC_URL = "jdbc:h2:/app/output/bankdb;MODE=DB2";

    private static final Charset UTF8 = Charset.forName("UTF-8");

    private static final File DATA_DIR = new File("/app/data");
    private static final File OUT_DIR = new File("/app/output");

    private static final File ACCOUNTS_CSV = new File(DATA_DIR, "accounts.csv");
    private static final File TXNS_CSV = new File(DATA_DIR, "transactions.csv");
    private static final File BIZ_DATE_TXT = new File(DATA_DIR, "biz_date.txt");
    private static final File FX_RATES_CSV = new File(DATA_DIR, "fx_rates.csv");
    private static final File FX_PIVOTS_CSV = new File(DATA_DIR, "fx_pivots.csv");
    private static final File FEE_RULES_CSV = new File(DATA_DIR, "fee_rules.csv");

    private static final File INTEREST_CSV = new File(OUT_DIR, "interest.csv");
    private static final File EXCEPTIONS_CSV = new File(OUT_DIR, "exceptions.csv");
    private static final File STATS_JSON = new File(OUT_DIR, "stats.json");

    private static final BigDecimal BD_0 = new BigDecimal("0");
    private static final BigDecimal BD_365 = new BigDecimal("365");

    private static final RoundingMode RM = RoundingMode.HALF_EVEN;

    private static final SimpleDateFormat DATE_FMT = new SimpleDateFormat("yyyy-MM-dd");
    static {
        DATE_FMT.setLenient(false);
        DATE_FMT.setTimeZone(TimeZone.getTimeZone("UTC"));
    }

    private static class Account {
        String accountId;
        int openedEpochDay;
        BigDecimal startBalance2;
        BigDecimal baseApr;
        BigDecimal promoApr;
        int promoDays;
        BigDecimal tierThreshold2;
        BigDecimal tierApr;
        String currency;
        String feePlan;
    }

    private static class Txn {
        int rowNum; // 1-based data row
        String txId;
        String accountId;
        int effectiveEpochDay;
        String effectiveDateStr;
        BigDecimal amount2;
        String currency;
        String status;
        String reversalOf;
    }

    private static class FeeRule {
        String plan;
        String appliesTo; // DEBIT/CREDIT/ALL
        BigDecimal flat2;
        BigDecimal pct;
        BigDecimal min2;
        BigDecimal max2;
    }

    private static class FxRate {
        int rateEpochDay;
        String rateDateStr;
        String from;
        String to;
        BigDecimal rate; // as provided
    }

    private static class FxResolver {
        // key: from|to => list of rates
        private final Map<String, List<FxRate>> byPair = new HashMap<String, List<FxRate>>();
        private final List<String> pivots;

        FxResolver(List<FxRate> rates, List<String> pivots) {
            this.pivots = pivots;
            for (FxRate r : rates) {
                String k = key(r.from, r.to);
                List<FxRate> lst = byPair.get(k);
                if (lst == null) {
                    lst = new ArrayList<FxRate>();
                    byPair.put(k, lst);
                }
                lst.add(r);
            }
            // sort each list by rate_date asc for easier scanning
            for (List<FxRate> lst : byPair.values()) {
                Collections.sort(lst, new Comparator<FxRate>() {
                    public int compare(FxRate a, FxRate b) {
                        return a.rateEpochDay - b.rateEpochDay;
                    }
                });
            }
        }

        private static String key(String from, String to) {
            return from + "|" + to;
        }

        private FxRate latestLE(String from, String to, int effectiveEpochDay) {
            List<FxRate> lst = byPair.get(key(from, to));
            if (lst == null || lst.isEmpty()) return null;
            FxRate best = null;
            for (int i = 0; i < lst.size(); i++) {
                FxRate r = lst.get(i);
                if (r.rateEpochDay <= effectiveEpochDay) {
                    best = r;
                } else {
                    break;
                }
            }
            return best;
        }

        // Direct/reverse only (no pivots)
        private BigDecimal resolveDirectOrReverse(String from, String to, int effectiveEpochDay) {
            if (from.equals(to)) return BigDecimal.ONE.setScale(10, RM);

            FxRate direct = latestLE(from, to, effectiveEpochDay);
            FxRate reverse = latestLE(to, from, effectiveEpochDay);

            if (direct == null && reverse == null) return null;

            boolean useDirect;
            if (direct != null && reverse != null) {
                if (direct.rateEpochDay > reverse.rateEpochDay) {
                    useDirect = true;
                } else if (direct.rateEpochDay < reverse.rateEpochDay) {
                    useDirect = false;
                } else {
                    // tie => use direct
                    useDirect = true;
                }
            } else {
                useDirect = (direct != null);
            }

            if (useDirect) {
                return direct.rate.setScale(10, RM);
            } else {
                // reverse exists: rate = 1/reverse, HALF_EVEN 10dp
                return BigDecimal.ONE.divide(reverse.rate, 10, RM);
            }
        }

        BigDecimal resolve(String from, String to, int effectiveEpochDay) {
            BigDecimal r = resolveDirectOrReverse(from, to, effectiveEpochDay);
            if (r != null) return r;

            // pivots in order; first successful wins; skip pivot equal to from/to
            for (int i = 0; i < pivots.size(); i++) {
                String p = pivots.get(i);
                if (p.equals(from) || p.equals(to)) continue;
                BigDecimal leg1 = resolveDirectOrReverse(from, p, effectiveEpochDay);
                if (leg1 == null) continue;
                BigDecimal leg2 = resolveDirectOrReverse(p, to, effectiveEpochDay);
                if (leg2 == null) continue;
                return leg1.multiply(leg2).setScale(10, RM);
            }
            return null;
        }
    }

    private static int toEpochDay(String yyyyMmDd) throws ParseException {
        Date d = DATE_FMT.parse(yyyyMmDd);
        Calendar c = Calendar.getInstance(TimeZone.getTimeZone("UTC"));
        c.setTime(d);
        // Normalize to midnight UTC
        c.set(Calendar.HOUR_OF_DAY, 0);
        c.set(Calendar.MINUTE, 0);
        c.set(Calendar.SECOND, 0);
        c.set(Calendar.MILLISECOND, 0);
        long millis = c.getTimeInMillis();
        return (int)(millis / 86400000L);
    }

    private static String readTrimmed(File f) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), UTF8));
        try {
            String s = br.readLine();
            if (s == null) return "";
            return s.trim();
        } finally {
            br.close();
        }
    }

    private static List<String[]> readCsv(File f) throws IOException {
        List<String[]> rows = new ArrayList<String[]>();
        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), UTF8));
        try {
            String line;
            while ((line = br.readLine()) != null) {
                // No quoted commas expected in provided legacy files
                rows.add(splitCsvLine(line));
            }
        } finally {
            br.close();
        }
        return rows;
    }

    private static String[] splitCsvLine(String line) {
        // Minimal CSV split (no escaping/quotes)
        List<String> parts = new ArrayList<String>();
        int start = 0;
        for (int i = 0; i < line.length(); i++) {
            if (line.charAt(i) == ',') {
                parts.add(line.substring(start, i));
                start = i + 1;
            }
        }
        parts.add(line.substring(start));
        String[] out = new String[parts.size()];
        for (int i = 0; i < parts.size(); i++) out[i] = parts.get(i);
        return out;
    }

    private static BigDecimal bd2(String s) {
        return new BigDecimal(s).setScale(2, RM);
    }

    private static BigDecimal bd(String s) {
        return new BigDecimal(s);
    }

    private static void ensureCleanOutputDir() throws IOException {
        if (!OUT_DIR.exists()) {
            if (!OUT_DIR.mkdirs()) throw new IOException("Failed to create " + OUT_DIR);
        }
        // Deterministic reruns: remove prior outputs if present
        deleteIfExists(INTEREST_CSV);
        deleteIfExists(EXCEPTIONS_CSV);
        deleteIfExists(STATS_JSON);
        deleteIfExists(new File(OUT_DIR, "bankdb.h2.db"));
        deleteIfExists(new File(OUT_DIR, "bankdb.trace.db"));
        deleteIfExists(new File(OUT_DIR, "bankdb.lock.db"));
    }

    private static void deleteIfExists(File f) {
        if (f.exists()) {
            // best-effort
            f.delete();
        }
    }

    private static String md5Hex(byte[] bytes) throws Exception {
        MessageDigest md = MessageDigest.getInstance("MD5");
        md.update(bytes);
        byte[] dig = md.digest();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < dig.length; i++) {
            int b = dig[i] & 0xff;
            if (b < 16) sb.append('0');
            sb.append(Integer.toHexString(b));
        }
        return sb.toString();
    }

    private static byte[] readAllBytes(File f) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        InputStream in = new FileInputStream(f);
        try {
            byte[] buf = new byte[8192];
            int n;
            while ((n = in.read(buf)) != -1) {
                baos.write(buf, 0, n);
            }
        } finally {
            in.close();
        }
        return baos.toByteArray();
    }

    private static void writeUtf8(File f, String content, boolean endWithNewline) throws IOException {
        OutputStream out = new FileOutputStream(f);
        try {
            Writer w = new OutputStreamWriter(out, UTF8);
            try {
                w.write(content);
                if (endWithNewline) w.write("\n");
            } finally {
                w.close();
            }
        } finally {
            out.close();
        }
    }

    public static void main(String[] args) throws Exception {
        ensureCleanOutputDir();

        String bizDateStr = readTrimmed(BIZ_DATE_TXT);
        int bizEpochDay = toEpochDay(bizDateStr);

        Map<String, Account> accounts = loadAccounts();
        List<Txn> txns = loadTxns();
        List<FxRate> fxRates = loadFxRates();
        List<String> pivots = loadPivots();
        FxResolver fx = new FxResolver(fxRates, pivots);
        Map<String, FeeRule> feeRules = loadFeeRules();

        // Build set of tx_ids in file
        Set<String> txIdsInFile = new HashSet<String>();
        for (int i = 0; i < txns.size(); i++) {
            txIdsInFile.add(txns.get(i).txId);
        }

        // Determine REVERSED set: if reversal_of points to any tx_id in file, both rows are REVERSED
        Set<String> reversedTxIds = new HashSet<String>();
        for (int i = 0; i < txns.size(); i++) {
            Txn t = txns.get(i);
            if (t.reversalOf != null && t.reversalOf.length() > 0) {
                if (txIdsInFile.contains(t.reversalOf)) {
                    reversedTxIds.add(t.txId);
                    reversedTxIds.add(t.reversalOf);
                }
            }
        }

        // Track duplicates (any later tx_id is DUPLICATE, even if first was invalid)
        Set<String> seenTxIds = new HashSet<String>();

        // Collect exceptions in file order
        List<String[]> exceptions = new ArrayList<String[]>(); // {row_num, tx_id, reason}

        // Aggregate valid adjusted sums per account
        Map<String, BigDecimal> adjustedSumByAccount = new HashMap<String, BigDecimal>();

        int validTxs = 0;
        int skippedTxs = 0;

        for (int i = 0; i < txns.size(); i++) {
            Txn t = txns.get(i);
            String reason = null;

            // reason order as specified
            if (reversedTxIds.contains(t.txId)) {
                reason = "REVERSED";
            } else if (t.reversalOf != null && t.reversalOf.length() > 0 && !txIdsInFile.contains(t.reversalOf)) {
                reason = "REVERSAL_MISSING";
            } else {
                // FX_MISSING (before FX)
                Account a = accounts.get(t.accountId);
                if (a == null) {
                    reason = "FX_MISSING";
                } else if (!t.currency.equals(a.currency)) {
                    BigDecimal rate = fx.resolve(t.currency, a.currency, t.effectiveEpochDay);
                    if (rate == null) {
                        reason = "FX_MISSING";
                    }
                }
            }

            if (reason == null) {
                if (t.effectiveEpochDay > bizEpochDay) {
                    reason = "AFTER_BIZ_DATE";
                }
            }
            if (reason == null) {
                if (!"POSTED".equals(t.status)) {
                    reason = t.status;
                }
            }
            if (reason == null) {
                if (seenTxIds.contains(t.txId)) {
                    reason = "DUPLICATE";
                }
            }

            // Record first appearance regardless of validity
            if (!seenTxIds.contains(t.txId)) seenTxIds.add(t.txId);

            if (reason != null) {
                skippedTxs++;
                exceptions.add(new String[] { String.valueOf(t.rowNum), t.txId, reason });
                continue;
            }

            // valid tx: compute adjusted in account currency
            Account a = accounts.get(t.accountId);
            BigDecimal amountAcct10;
            if (t.currency.equals(a.currency)) {
                amountAcct10 = t.amount2.setScale(10, RM);
            } else {
                BigDecimal rate = fx.resolve(t.currency, a.currency, t.effectiveEpochDay);
                // should exist due to earlier validation
                amountAcct10 = t.amount2.setScale(10, RM).multiply(rate).setScale(10, RM);
            }

            FeeRule fr = feeRules.get(a.feePlan);
            BigDecimal fee2 = BD_0.setScale(2, RM);
            if (fr != null) {
                boolean isDebit = amountAcct10.signum() < 0;
                boolean isCredit = amountAcct10.signum() > 0;
                boolean applies;
                if ("ALL".equals(fr.appliesTo)) {
                    applies = true;
                } else if ("DEBIT".equals(fr.appliesTo)) {
                    applies = isDebit;
                } else if ("CREDIT".equals(fr.appliesTo)) {
                    applies = isCredit;
                } else {
                    applies = false;
                }

                if (applies) {
                    BigDecimal absAmt10 = amountAcct10.abs();
                    BigDecimal rawFee = fr.flat2.setScale(10, RM).add(fr.pct.multiply(absAmt10)).setScale(10, RM);
                    BigDecimal feeRounded2 = rawFee.setScale(2, RM);
                    if (feeRounded2.compareTo(fr.min2) < 0) feeRounded2 = fr.min2;
                    if (feeRounded2.compareTo(fr.max2) > 0) feeRounded2 = fr.max2;
                    fee2 = feeRounded2.setScale(2, RM);
                }
            }

            BigDecimal adjusted2 = amountAcct10.setScale(2, RM).subtract(fee2).setScale(2, RM);

            BigDecimal prev = adjustedSumByAccount.get(a.accountId);
            if (prev == null) prev = BD_0.setScale(2, RM);
            adjustedSumByAccount.put(a.accountId, prev.add(adjusted2).setScale(2, RM));

            validTxs++;
        }

        // Compute per-account interest lines
        List<String> accountIds = new ArrayList<String>(accounts.keySet());
        Collections.sort(accountIds);

        class InterestLine {
            String accountId;
            String bizDate;
            BigDecimal eod2;
            BigDecimal apr6;
            BigDecimal dailyInterestRaw10;
            BigDecimal dailyInterest2;
        }

        List<InterestLine> lines = new ArrayList<InterestLine>();
        BigDecimal totalInterestRaw10 = BD_0.setScale(10, RM);

        for (int i = 0; i < accountIds.size(); i++) {
            String aid = accountIds.get(i);
            Account a = accounts.get(aid);
            BigDecimal sumAdj2 = adjustedSumByAccount.get(aid);
            if (sumAdj2 == null) sumAdj2 = BD_0.setScale(2, RM);

            BigDecimal eod2 = a.startBalance2.add(sumAdj2).setScale(2, RM);

            int daysSinceOpened = bizEpochDay - a.openedEpochDay;
            boolean promo = (a.promoDays > 0) && (daysSinceOpened < a.promoDays);
            boolean tier = eod2.compareTo(a.tierThreshold2) >= 0;

            BigDecimal apr = a.baseApr;
            if (tier) apr = apr.add(a.tierApr);
            if (promo) apr = apr.add(a.promoApr);
            BigDecimal apr6 = apr.setScale(6, RM);

            BigDecimal principal2 = (eod2.compareTo(BD_0) > 0) ? eod2 : BD_0.setScale(2, RM);
            BigDecimal dailyRaw10 = principal2.setScale(10, RM)
                    .multiply(apr.setScale(10, RM)).setScale(10, RM)
                    .divide(BD_365, 10, RM);
            BigDecimal daily2 = dailyRaw10.setScale(2, RM);

            totalInterestRaw10 = totalInterestRaw10.add(dailyRaw10).setScale(10, RM);

            InterestLine il = new InterestLine();
            il.accountId = aid;
            il.bizDate = bizDateStr;
            il.eod2 = eod2;
            il.apr6 = apr6;
            il.dailyInterestRaw10 = dailyRaw10;
            il.dailyInterest2 = daily2;
            lines.add(il);
        }

        // Write interest.csv (LF + trailing newline)
        StringBuilder interest = new StringBuilder();
        interest.append("account_id,biz_date,eod_balance,apr,daily_interest\n");
        for (int i = 0; i < lines.size(); i++) {
            InterestLine il = lines.get(i);
            interest.append(il.accountId).append(',')
                    .append(il.bizDate).append(',')
                    .append(il.eod2.toPlainString()).append(',')
                    .append(il.apr6.toPlainString()).append(',')
                    .append(il.dailyInterest2.toPlainString())
                    .append("\n");
        }
        writeUtf8(INTEREST_CSV, interest.toString(), false); // already ends with newline

        // Write exceptions.csv (LF + trailing newline)
        StringBuilder exc = new StringBuilder();
        exc.append("row_num,tx_id,reason\n");
        for (int i = 0; i < exceptions.size(); i++) {
            String[] e = exceptions.get(i);
            exc.append(e[0]).append(',').append(e[1]).append(',').append(e[2]).append("\n");
        }
        writeUtf8(EXCEPTIONS_CSV, exc.toString(), false);

        // md5 of interest.csv bytes
        byte[] interestBytes = readAllBytes(INTEREST_CSV);
        String reportMd5 = md5Hex(interestBytes);

        // total_interest: sum(daily_interest_raw keep 10dp) rounded to 2dp
        BigDecimal totalInterest2 = totalInterestRaw10.setScale(2, RM);

        // Write stats.json single line without newline
        String json = "{" +
                "\"biz_date\":\"" + bizDateStr + "\"," +
                "\"accounts\":" + accounts.size() + "," +
                "\"valid_txs\":" + validTxs + "," +
                "\"skipped_txs\":" + skippedTxs + "," +
                "\"total_interest\":\"" + totalInterest2.toPlainString() + "\"," +
                "\"report_md5\":\"" + reportMd5 + "\"" +
                "}";
        writeUtf8(STATS_JSON, json, false);

        // Build H2 database
        buildDb(accounts, txns, bizDateStr, accounts.size(), validTxs, skippedTxs, reportMd5);
    }

    private static Map<String, Account> loadAccounts() throws Exception {
        List<String[]> rows = readCsv(ACCOUNTS_CSV);
        if (rows.isEmpty()) throw new IOException("accounts.csv empty");
        Map<String, Integer> idx = headerIndex(rows.get(0));
        Map<String, Account> out = new HashMap<String, Account>();
        for (int i = 1; i < rows.size(); i++) {
            String[] r = rows.get(i);
            Account a = new Account();
            a.accountId = get(r, idx, "account_id");
            String openedAt = get(r, idx, "opened_at");
            a.openedEpochDay = toEpochDay(openedAt);
            a.startBalance2 = bd2(get(r, idx, "start_balance"));
            a.baseApr = bd(get(r, idx, "base_apr"));
            a.promoApr = bd(get(r, idx, "promo_apr"));
            a.promoDays = Integer.parseInt(get(r, idx, "promo_days"));
            a.tierThreshold2 = bd2(get(r, idx, "tier_threshold"));
            a.tierApr = bd(get(r, idx, "tier_apr"));
            a.currency = get(r, idx, "currency");
