        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < dig.length; i++) {
            int b = dig[i] & 0xff;
            if (b < 16) sb.append('0');
            sb.append(Integer.toHexString(b));
        }
        return sb.toString();
