  private static String[] split(String line){
    ArrayList<String> parts = new ArrayList<String>();
    int s=0;
    for(int i=0;i<line.length();i++) if(line.charAt(i)==','){ parts.add(line.substring(s,i)); s=i+1; }
    parts.add(line.substring(s));
    String[] out = new String[parts.size()];
    for(int i=0;i<parts.size();i++) out[i]=parts.get(i);
