  private static String pair(String f,String t){ return f+"|"+t; }

  private static FxRate latestLE(Map<String,List<FxRate>> byPair, String from, String to, int effDay){
    List<FxRate> lst = byPair.get(pair(from,to));
    if(lst==null) return null;
    FxRate best=null;
    for(int i=0;i<lst.size();i++){
      FxRate r=lst.get(i);
      if(r.day<=effDay) best=r; else break;
    }
    return best;
  }

  private static BigDecimal resolveDirectOrReverse(Map<String,List<FxRate>> byPair, String from, String to, int effDay){
    if(from.equals(to)) return BigDecimal.ONE.setScale(10, RM);
    FxRate direct = latestLE(byPair, from, to, effDay);
    FxRate reverse = latestLE(byPair, to, from, effDay);
    if(direct==null && reverse==null) return null;

    boolean useDirect;
    if(direct!=null && reverse!=null){
      if(direct.day>reverse.day) useDirect=true;
      else if(direct.day<reverse.day) useDirect=false;
      else useDirect=true; // tie => direct
    } else useDirect = (direct!=null);

    if(useDirect) return direct.rate.setScale(10, RM);
    return BigDecimal.ONE.divide(reverse.rate, 10, RM);
  }

  private static BigDecimal resolveFx(Map<String,List<FxRate>> byPair, List<String> pivots, String from, String to, int effDay){
    BigDecimal r = resolveDirectOrReverse(byPair, from, to, effDay);
    if(r!=null) return r;
    for(int i=0;i<pivots.size();i++){
      String p=pivots.get(i);
      if(p.equals(from) || p.equals(to)) continue;
      BigDecimal a = resolveDirectOrReverse(byPair, from, p, effDay);
      if(a==null) continue;
      BigDecimal b = resolveDirectOrReverse(byPair, p, to, effDay);
      if(b==null) continue;
      return a.multiply(b).setScale(10, RM);
    }
    return null;
  }

