    // index fx rates by pair, sorted by day
    HashMap<String,List<FxRate>> byPair = new HashMap<String,List<FxRate>>();
    for(int i=0;i<fxRates.size();i++){
      FxRate r=fxRates.get(i);
      String k=pair(r.from,r.to);
      List<FxRate> lst=byPair.get(k);
      if(lst==null){ lst=new ArrayList<FxRate>(); byPair.put(k,lst); }
      lst.add(r);
    }
    for(Iterator<Map.Entry<String,List<FxRate>>> it=byPair.entrySet().iterator(); it.hasNext(); ){
      Map.Entry<String,List<FxRate>> e=it.next();
      Collections.sort(e.getValue(), new Comparator<FxRate>(){ public int compare(FxRate a, FxRate b){ return a.day-b.day; }});
    }

    HashSet<String> txIdsInFile = new HashSet<String>();
    for(int i=0;i<txns.size();i++) txIdsInFile.add(txns.get(i).txId);

    // REVERSED: both rows if reversal_of points to any tx_id in file
    HashSet<String> reversed = new HashSet<String>();
    for(int i=0;i<txns.size();i++){
      Txn t=txns.get(i);
      if(t.reversalOf!=null && t.reversalOf.length()>0 && txIdsInFile.contains(t.reversalOf)){
        reversed.add(t.txId);
        reversed.add(t.reversalOf);
      }
    }

    HashSet<String> seen = new HashSet<String>();
    ArrayList<String[]> exc = new ArrayList<String[]>();
    HashMap<String,BigDecimal> sumAdj2 = new HashMap<String,BigDecimal>();
    int valid=0, skipped=0;

    for(int i=0;i<txns.size();i++){
      Txn t=txns.get(i);
      String reason=null;

      if(reversed.contains(t.txId)) reason="REVERSED";
      else if(t.reversalOf!=null && t.reversalOf.length()>0 && !txIdsInFile.contains(t.reversalOf)) reason="REVERSAL_MISSING";
      else {
        Account a=accts.get(t.acctId);
        if(a==null) reason="FX_MISSING";
        else if(!t.ccy.equals(a.ccy)){
          BigDecimal rate=resolveFx(byPair,pivots,t.ccy,a.ccy,t.effDay);
          if(rate==null) reason="FX_MISSING";
        }
      }
      if(reason==null && t.effDay>bizDay) reason="AFTER_BIZ_DATE";
      if(reason==null && !"POSTED".equals(t.status)) reason=t.status;
      if(reason==null && seen.contains(t.txId)) reason="DUPLICATE";

      if(!seen.contains(t.txId)) seen.add(t.txId);

      if(reason!=null){
        skipped++;
        exc.add(new String[]{String.valueOf(t.rowNum), t.txId, reason});
        continue;
      }

      Account a=accts.get(t.acctId);
      BigDecimal amtAcct10;
      if(t.ccy.equals(a.ccy)) amtAcct10=t.amt2.setScale(10,RM);
      else {
        BigDecimal rate=resolveFx(byPair,pivots,t.ccy,a.ccy,t.effDay);
        amtAcct10=t.amt2.setScale(10,RM).multiply(rate).setScale(10,RM);
      }

      FeeRule fr=fees.get(a.feePlan);
      BigDecimal fee2=BD0.setScale(2,RM);
      if(fr!=null){
        boolean isDebit=amtAcct10.signum()<0;
        boolean isCredit=amtAcct10.signum()>0;
        boolean applies = "ALL".equals(fr.applies) || ("DEBIT".equals(fr.applies)&&isDebit) || ("CREDIT".equals(fr.applies)&&isCredit);
        if(applies){
          BigDecimal raw10 = fr.flat2.setScale(10,RM).add(fr.pct.multiply(amtAcct10.abs())).setScale(10,RM);
          BigDecimal f2 = raw10.setScale(2,RM);
          if(f2.compareTo(fr.min2)<0) f2=fr.min2;
          if(f2.compareTo(fr.max2)>0) f2=fr.max2;
          fee2=f2.setScale(2,RM);
        }
      }

      BigDecimal adj2 = amtAcct10.setScale(2,RM).subtract(fee2).setScale(2,RM);
      BigDecimal prev=sumAdj2.get(a.id);
      if(prev==null) prev=BD0.setScale(2,RM);
      sumAdj2.put(a.id, prev.add(adj2).setScale(2,RM));
      valid++;
    }

    ArrayList<String> acctIds=new ArrayList<String>(accts.keySet());
    Collections.sort(acctIds);

    StringBuilder interest=new StringBuilder();
    interest.append("account_id,biz_date,eod_balance,apr,daily_interest\n");
    BigDecimal totalRaw10=BD0.setScale(10,RM);

    for(int i=0;i<acctIds.size();i++){
      Account a=accts.get(acctIds.get(i));
      BigDecimal adj=sumAdj2.get(a.id); if(adj==null) adj=BD0.setScale(2,RM);
      BigDecimal eod2=a.start2.add(adj).setScale(2,RM);

      int daysSince = bizDay - a.openedDay;
      boolean promo = a.promoDays>0 && daysSince < a.promoDays;
      boolean tier = eod2.compareTo(a.tierThr2) >= 0;

      BigDecimal apr=a.baseApr;
      if(tier) apr=apr.add(a.tierApr);
      if(promo) apr=apr.add(a.promoApr);
      BigDecimal apr6=apr.setScale(6,RM);

      BigDecimal principal2 = eod2.compareTo(BD0)>0 ? eod2 : BD0.setScale(2,RM);
      BigDecimal dailyRaw10 = principal2.setScale(10,RM).multiply(apr.setScale(10,RM)).setScale(10,RM).divide(BD365,10,RM);
      BigDecimal daily2 = dailyRaw10.setScale(2,RM);
      totalRaw10 = totalRaw10.add(dailyRaw10).setScale(10,RM);

      interest.append(a.id).append(',').append(bizDate).append(',')
        .append(eod2.toPlainString()).append(',').append(apr6.toPlainString()).append(',')
        .append(daily2.toPlainString()).append("\n");
    }

    writeUtf8(INTEREST_CSV, interest.toString());

    StringBuilder ex=new StringBuilder();
    ex.append("row_num,tx_id,reason\n");
    for(int i=0;i<exc.size();i++){
      String[] e=exc.get(i);
      ex.append(e[0]).append(',').append(e[1]).append(',').append(e[2]).append("\n");
    }
    writeUtf8(EXCEPTIONS_CSV, ex.toString());

    String reportMd5 = md5(readAll(INTEREST_CSV));
    BigDecimal total2 = totalRaw10.setScale(2,RM);

    String json = "{"+
      "\"biz_date\":\""+bizDate+"\","+
      "\"accounts\":"+accts.size()+","+
      "\"valid_txs\":"+valid+","+
      "\"skipped_txs\":"+skipped+","+
      "\"total_interest\":\""+total2.toPlainString()+"\","+
      "\"report_md5\":\""+reportMd5+"\""+
      "}";
    writeUtf8(STATS_JSON, json);

    buildDb(accts, txns, bizDate, accts.size(), valid, skipped, reportMd5);
  }
}
